import json, subprocess, sys
from pathlib import Path
OUT=Path('/workspace/work/pattern_batches'); OUT.mkdir(exist_ok=True)
PITCHES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
PC={p:i for i,p in enumerate(PITCHES)}

def pitch(pc,octave):
    if isinstance(pc,str): pc=PC[pc]
    n=octave*12+int(pc)
    o=n//12; name=PITCHES[n%12]
    return ('C-' if name=='C' else name+'-' if len(name)==1 else name)+str(o)

def midi(pc,octave): return octave*12+(PC[pc] if isinstance(pc,str) else pc)
def fmt(n): return pitch(n%12,n//12)
def addi(n,i): return n+i

CHORDS={
 'F#m':('F#',3), 'D':('D',4), 'A':('A',4), 'E':('E',4), 'Bm':('B',3)
}
# 16th-row steps in a bar, eight-note melodic phrases.
MAIN={
 'F#m':['C#6','A5','F#5','A5','C#6','E6','C#6','A5'],
