 'A'  :['C#6','E6','G#6','A6','G#6','E6','C#6','B5'],
 'E'  :['G#5','B5','D6','E6','D6','C#6','B5','G#5'],
 'Bm' :['D6','F#6','A6','B6','A6','F#6','D6','C#6']}

# Each order position is a distinct four-bar scene. All standard sections turn back to F# minor.
sections={
 0: dict(chords=['F#m','D','A','E'],pad=True,arp='intro',drums='none',lead='none',bass=None,sub=None),
 1: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='warm',lead='none',bass=(2,4),sub=(3,4)),
