 4: dict(chords=['F#m','D','A','E'],pad=True,arp='build',drums='build',lead='rising',bass=(0,4),sub=(0,4),riser=True),
 5: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='main_third',bass=(0,4),sub=(0,4),crash=True),
 6: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='alt_third',bass=(0,4),sub=(0,4)),
 7: dict(chords=['F#m','D','A','E'],pad=True,arp='break',drums='none',lead='none',bass=None,sub=None),
 8: dict(chords=['F#m','D','A','E'],pad=True,arp='build2',drums='build2',lead='rise_late',bass=(1,4),sub=(2,4),riser=True),
 9: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='main_oct',bass=(0,4),sub=(0,4),crash=True),
10: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='alt_third',bass=(0,4),sub=(0,4)),
11: dict(chords=['Bm','D','A','E'],pad=True,arp='bridge',drums='bridge',lead='bridge',bass=(0,4),sub=(0,4)),
12: dict(chords=['F#m','D','A','E'],pad=True,arp='build2',drums='finalbuild',lead='none',bass=(2,4),sub=(3,4),riser=True),
13: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='main_third',bass=(0,4),sub=(0,4),crash=True),
14: dict(chords=['F#m','D','A','E'],pad=True,arp='full',drums='full',lead='final_mix',bass=(0,4),sub=(0,4),crash=True,crash2=True),
15: dict(chords=['D','A','E','E'],pad=True,arp='outro',drums='none',lead='none',bass=(0,2),sub=(0,2)),
}
# channel/instrument mapping (channels are zero-based)
LEAD_A,LEAD_B,PLUCK,PAD_L,PAD_C,PAD_R,BASS,SUB,KICK,SNARE,HAT_C,HAT_O=range(12)
I_LEAD_A,I_LEAD_B,I_PLUCK,I_PAD_L,I_PAD_C,I_PAD_R,I_BASS,I_SUB,I_KICK,I_SNARE,I_HAT_C,I_HAT_O,I_CRASH,I_RISER=range(1,15)
# event map (p,row,ch)->cell
E={}
def put(p,row,ch,note,inst=None):
    key=(p,row,ch)
    cell={'name':'pattern_set_cell','arguments':{'pattern':p,'row':row,'channel':ch,'note':note}}
    if inst is not None: cell['arguments']['instrument']=inst
    E[key]=cell

def off(p,row,ch): put(p,row,ch,97,None)

def noteval(s):
    # standard XM names are used directly in the API
    return s

def chord_info(name):
    root,quality=CHORDS[name]
    r=PC[root]
    third=3 if quality==3 else 4
    return r,third,7

# Explicit key-diatonic third for lush split supersaws.
SCALE=[9,11,1,2,4,6,8] # A major / F# natural minor
SCALE_INDEX={v:i for i,v in enumerate(SCALE)}
def diatonic_third(note_string):
    # note string like F#5
    s=note_string
    octave=int(s[-1]); nm=s[:-1]
    pc=PC[nm]
    m=octave*12+pc
    idx=SCALE_INDEX.get(pc)
    if idx is None: return fmt(m+3)
    idx2=idx+2
    pc2=SCALE[idx2%7]
    oct2=octave+(idx2//7)
    return pitch(pc2,oct2)

def add_pad(p,chords):
    for bar,cname in enumerate(chords):
        r,t,f=chord_info(cname); base=bar*16
        put(p,base,PAD_L,pitch(r,3),I_PAD_L)
        put(p,base,PAD_C,pitch((r+t)%12,3+(r+t)//12),I_PAD_C)
        # Fifth above the root, comfortably above the low pad voices.
        put(p,base,PAD_R,pitch((r+f)%12,4+(r+f)//12),I_PAD_R)

def add_arp(p,chords,mode,startbar=0,endbar=4):
    for bar in range(startbar,endbar):
        cname=chords[bar]; r,t,f=chord_info(cname); b=bar*16
        r4=pitch(r,4); third4=pitch((r+t)%12,4+(r+t)//12); fifth4=pitch((r+7)%12,4+(r+7)//12)
        r5=pitch(r,5); third5=pitch((r+t)%12,5+(r+t)//12); fifth5=pitch((r+7)%12,5+(r+7)//12)
        r6=pitch(r,6); third6=pitch((r+t)%12,6+(r+t)//12)
        if mode=='intro':
            seq=[r4,fifth4,third5,fifth4]; rows=[0,4,8,12]
        elif mode=='outro':
            seq=[r4,fifth4,third5,fifth4]; rows=[0,4,8,12] if bar<2 else []
        elif mode=='break':
            # Less rhythmic, fragile four-note upper-register figure.
            seq=[third5,r5,fifth5,r5]; rows=[0,4,8,12]
        elif mode=='bridge':
            seq=[r4,fifth4,r5,fifth4,third5,fifth4,r5,fifth4]; rows=list(range(0,16,2))
        elif mode=='full':
            seq=[r4,fifth4,r5,fifth4,third5,fifth4,r5,fifth4]; rows=list(range(0,16,2))
        elif mode=='build':
            seq=[r4,third4,fifth4,r5,third5,fifth5,r6,third6,
                 r6,fifth5,r6,third6,fifth6,r6,fifth6,third6]
            rows=list(range(16))
        elif mode=='build2':
            if bar<2:
                seq=[r4,fifth4,third5,fifth4]; rows=[0,4,8,12]
            else:
                seq=[r4,third4,fifth4,r5,third5,fifth5,r6,third6,
                     r6,fifth5,r6,third6,fifth6,r6,fifth6,third6]
                rows=list(range(16))
        else: continue
        for row,nn in zip(rows,seq): put(p,b+row,PLUCK,nn,I_PLUCK)

def add_bass(p,chords,bounds,sub=False,variant=0):
    if bounds is None:
        off(p,0,SUB if sub else BASS); return
    start,end=bounds
    if start>0: off(p,0,SUB if sub else BASS)
    if end<4: off(p,end*16,SUB if sub else BASS)
    ch=SUB if sub else BASS; inst=I_SUB if sub else I_BASS
    for bar in range(start,end):
        r,t,f=chord_info(chords[bar]); base=bar*16
        root2=pitch(r,2)
        if sub:
            put(p,base,ch,pitch(r,1),inst)
            put(p,base+8,ch,pitch(r,1),inst)
        else:
            third2=pitch((r+t)%12,2+(r+t)//12)
            fifth2=pitch((r+7)%12,2+(r+7)//12)
            root3=pitch(r,3)
            third3=pitch((r+t)%12,3+(r+t)//12)
            if variant%2:
                seq=[root2,fifth2,root3,fifth2,root2,third3,fifth2,third2]
            else:
                seq=[root2,root2,fifth2,root2,root3,fifth2,third3,fifth2]
            for step,nn in enumerate(seq): put(p,base+step*2,BASS,nn,I_BASS)

def add_lead_phrase(p,chords,phrase,mode):
    for bar,cname in enumerate(chords):
        seq=phrase[cname]; base=bar*16
        for i,nn in enumerate(seq):
            row=base+2*i
            put(p,row,LEAD_A,nn,I_LEAD_A)
            if mode=='main_sparse':
                if i in (0,4): put(p,row,LEAD_B,diatonic_third(nn),I_LEAD_B)
            elif mode=='third': put(p,row,LEAD_B,diatonic_third(nn),I_LEAD_B)
            elif mode=='oct':
                if i in (0,2,4,6):
                    # Gentle octave accents instead of a second full melody.
                    m=(int(nn[-1])*12 + PC[nn[:-1]])+12
                    put(p,row,LEAD_B,fmt(m),I_LEAD_B)
            elif mode=='final_mix':
                # Trade a diatonic third for an octave on structural eighths.
                m=int(nn[-1])*12+PC[nn[:-1]]
                put(p,row,LEAD_B,fmt(m+12) if i in (0,4) else diatonic_third(nn),I_LEAD_B)

