        r,t,f=chord_info(cname); base=bar*16
        r5=pitch(r,5); t5=pitch((r+t)%12,5+(r+t)//12); f5=pitch((r+7)%12,5+(r+7)//12)
        r6=pitch(r,6); t6=pitch((r+t)%12,6+(r+t)//12); f6=pitch((r+7)%12,6+(r+7)//12)
        seq=[r5,t5,f5,r6,t6,f6,r6,t6]
        # During the earlier build, double the rhythmic rate on the last bar.
        if not late or bar==3:
            for i,nn in enumerate(seq): put(p,base+2*i,LEAD_A,nn,I_LEAD_A)
        else:
            for i,nn in enumerate(seq[:4]): put(p,base+4*i,LEAD_A,nn,I_LEAD_A)

def add_bridge_lead(p,chords):
